import{_ as i,o as n,c as a,a4 as l}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20251030205757380.DKU5diHb.png",p="/assets/image-20251030210533247.DUjpkkA6.png",e="/assets/image-20251030211355391.BjB1X85Y.png",h="/assets/image-20251030221518090.ANeF4Mjf.png",k="/assets/image-20251031101602362.YXKt2VlL.png",r="/assets/image-20251031095114165.WlD6oaqp.png",E="/assets/image-20251031095213872.DoNxLehJ.png",d="/assets/image-20251031095408911.Cmo3-dgV.png",g="/assets/image-20251031095711444.D1YnB-mV.png",o="/assets/image-20251031100022405.DmXnWmHf.png",c="/assets/image-20251031100222985.DeNN-xDA.png",y="/assets/image-20251031100340244.BgqBwXKy.png",F="/assets/image-20251031085235546.cnp1aLbJ.png",b="/assets/image-20251031090516298.B20-CI4b.png",w=JSON.parse("{\"title\":\"《宠知汇》应用案例热点技术解析\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"鸿蒙开发技巧/《宠知汇》应用案例热点技术解析/《宠知汇》应用案例热点技术解析.md\",\"filePath\":\"鸿蒙开发技巧/《宠知汇》应用案例热点技术解析/《宠知汇》应用案例热点技术解析.md\",\"lastUpdated\":1762865236000,\"__rawMarkdown\":\"# 《宠知汇》应用案例热点技术解析\\n\\n\\n\\n## 开篇\\n\\n《宠知汇》作为一款深度适配 HarmonyOS 的宠物主题应用，*汇聚专业养宠知识，构建全场景养护生态*，为\\n\\n宠物主人打造覆盖宠物生命周期的一站式智慧服务入口。\\n\\n依托鸿蒙系统的分布式能力与智能化特性，让科学养宠更简单、更便捷。\\n\\n《宠知汇》借助 HarmonyOS 的跨设备优势，实现手机、平板、智慧屏等多终端的无缝协同，成为宠物主人身边的 *移动养宠管家*。\\n\\n## 第一章：借助“一多”能力，实现全设备适配\\n\\n\\n\\n《宠知汇》通过 HarmonyOS 的**一次开发，多端部署**能力，实现了应用在不同设备形态上的完美适配。基于统一的 ArkTS 开发框架，应用能够智能识别设备类型和屏幕尺寸，自动调整界面布局和交互方式。\\n\\n ![image-20251030205757380](assets/image-20251030205757380.png)\\n\\n 需要掌握一次开发、多端部署的知识，就需要了解一多和三层架构的关系。\\n\\n- **一次开发、多端部署是目标**\\n\\n- **三层架构是具体实现**\\n\\n### 三层架构\\n\\n想象你要开发一个应用，就像建一栋能适配不同住户（设备）的智能公寓楼。三层架构就是把这栋楼分成三个部分，每层各司其职：\\n\\n1. **公共能力层（地下室和基础设施）**\\n   - 这是整栋楼的“地基”，包含水管、电网、网络线路等**共享资源**。\\n   - 在应用中，就是**公共组件**：比如统一的按钮样式、网络请求工具、数据管理库等。所有上层功能都能调用这些基础能力，避免重复造轮子。\\n   - **通俗说**：就像楼里的公用健身房和停车场，所有住户都能用，但不需要每家自己修。\\n2. **基础特性层（标准户型模块）**\\n   - 这层是预先设计好的**功能模块**，比如卧室、厨房、卫生间。每个模块独立且完整（高内聚），能灵活组合。\\n   - 在应用中，就是**核心功能**：比如登录模块、支付模块、视频播放模块等。这些模块可以打包成 **功能包**（Feature HAP），根据需要安装到不同设备。\\n   - **通俗说**：就像乐高积木，你可以用同样的积木块拼出不同房子，比如手机版用少量积木，平板版用更多积木。\\n3. **产品定制层（个性化装修和入口）**  \\n   - 这层是针对不同住户（设备）的**个性化定制**。比如给年轻人的公寓用现代风格，给家庭的用温馨风格。\\n   - 在应用中，就是**设备专属的UI和配置**：比如手机的简洁界面、平板的分屏布局、PC的窗口模式。这一层编译成 **入口包**（Entry HAP），作为用户直接交互的界面。\\n   - **通俗说**：同样是卧室模块，在手机上显示为底部标签，在平板上显示为侧边栏，但背后的功能（睡觉）是一样的。\\n\\n![image-20251030210533247](assets/image-20251030210533247.png)\\n\\n\\n\\n\\n\\n**为什么这样分层？**\\n\\n- **维护简单**：如果水管坏了（公共能力层更新），只需修一次，全楼受益。\\n- **灵活扩展**：想新增一个“智能厨房”（新功能），只需在基础特性层开发，然后轻松添加到不同户型（设备）。\\n- **复用性强**：同样的厨房模块，既能用在公寓，也能用在别墅（不同设备）。\\n\\n\\n\\n实际开发中，可以参考以下表格来了解三层架构。\\n\\n表格已提炼每一层的核心维度，覆盖开发中最需关注的 **产物、作用和规则**，便于快速查阅和对比。\\n\\n| 架构层级   | 核心编译产物                                                 | 核心作用                                    | 关键规则                                       |\\n| ---------- | ------------------------------------------------------------ | ------------------------------------------- | ---------------------------------------------- |\\n| 产品定制层 | Entry 类型 HAP（最终打包为.app 文件）                        | 作为应用主入口，针对不同设备定制 UI 和功能  | 支持一次编译生成多 HAP 组合，用于应用市场上架  |\\n| 基础特性层 | 1. 需 Ability：Feature 类型 HAP2. 无需 Ability：HAR 包 / HSP 包 | 提供独立功能模块，支撑上层产品需求          | 按 “是否需 Ability”“是否需按需加载” 选择产物   |\\n| 公共能力层 | HAR 包                                                       | 提供公共基础能力（接口 / 工具），提升复用率 | 仅允许产品定制层、基础特性层依赖，禁止反向依赖 |\\n\\n对应 《宠知汇》目录结构\\n\\n![image-20251030211355391](assets/image-20251030211355391.png)\\n\\n### 一次开发、多端部署\\n\\n根据一次开发、多端部署的理念，一多又可以分为**三种一多**，它们分别是 **界面级一多**、**工程级一多**和**能力级一多**。\\n\\n1. **工程级一多**是**基础和骨架**。它决定了代码怎么组织、怎么打包。\\n2. **功能级一多**是**神经和肌肉**。它让应用能感知并适应设备的硬件能力，确保功能上的兼容性。\\n3. **界面级一多**是**外表和皮肤**。它最终决定了用户在屏幕上看到的是什么样子，确保视觉和交互的完美体验。\\n\\n\\n\\n其中工程级一多，就是上面刚刚描述过的三层架构。\\n\\n\\n\\n### 功能级一多\\n\\n手机上支持拍照，手表上不支持，那么一套代码下，该如何完美解决？\\n\\n答案是借助 即**SystemCapability**，缩写**为SysCap**。\\n\\n和硬件相关的如摄像、麦克风、wifi等都是系统的能力。每一个系统能力对应多个API，支持某个系统能力也等于支持这些API调用。\\n\\n系统能力又分为**支持能力集**、**联想能力集**和**要求能力集**三个核心概念。\\n\\n- **支持能力集**：设备具备的系统能力集合，在设备配置文件中配置。\\n- **要求能力集**：应用需要的系统能力集合，在应用配置文件中配置。\\n- **联想能力集**：开发应用时DevEco Studio可联想的API所在的系统能力集合，在应用配置文件中配置。\\n\\n开发多设备应用时，工程中默认的**要求能力集**是多个设备支持能力集的交集，默认的**联想能力集**是多个设备支持能力集的并集。\\n\\n如果某个系统能力没有写入应用的要求能力集中，那么在使用前需要判断设备是否支持该系统能力。\\n\\n- 方法1：canIUse()接口帮助开发者来判断该设备是否支持某个特定的syscap。\\n\\n  ```go\\n  if (canIUse('SystemCapability.Communication.NFC.Core')) {\\n    hilog.info(0x0000, 'Index', `该设备支持SystemCapability.Communication.NFC.Core`);\\n  } else {\\n    hilog.error(0x0000, 'Index', `该设备不支持SystemCapability.Communication.NFC.Core`);\\n  }\\n  ```\\n\\n  [Index.ets](https://gitee.com/harmonyos_samples/BestPracticeSnippets/blob/master/ArkUI/orientationDevelopment/entry/src/main/ets/pages/Index.ets#L13-L17)\\n\\n- 方法2：开发者可通过import的方式将模块导入，若当前设备不支持该模块，import的结果为undefined，开发者在使用其API时，需要判断其是否存在。\\n\\n  ```typescript\\n  import { nfcController } from '@kit.ConnectivityKit';\\n  \\n  @Entry\\n  @Component\\n  struct Index {\\n    // ...\\n  \\n    canIUseNfc(): void {\\n      if (canIUse('SystemCapability.Communication.NFC.Core')) {\\n        hilog.info(0x0000, 'Index', `该设备支持SystemCapability.Communication.NFC.Core`);\\n      } else {\\n        hilog.error(0x0000, 'Index', `该设备不支持SystemCapability.Communication.NFC.Core`);\\n      }\\n      // ...\\n    }\\n    // ...\\n  }\\n  ```\\n\\n**配置联想能力集和要求能力集**\\n\\nDevEco Studio会根据创建的工程所支持的设备自动配置联想能力集和要求能力集，同时也支持开发者修改。\\n\\n```json\\n// syscap.json\\n{\\n    \\\"devices\\\": {\\n        \\\"general\\\": [            \\n            \\\"default\\\",\\n            \\\"tablet\\\"\\n        ],\\n        \\\"custom\\\": [            \\n            {\\n                \\\"Custom Device\\\": [\\n                    \\\"SystemCapability.Communication.SoftBus.Core\\\"\\n                ]\\n            }\\n        ]\\n    },\\n    \\\"development\\\": {             \\n        \\\"addedSysCaps\\\": [\\n            \\\"SystemCapability.Communication.NFC.Core\\\"\\n        ]\\n    },\\n    \\\"production\\\": {              \\n        \\\"addedSysCaps\\\": [],      \\n        \\\"removedSysCaps\\\": []     \\n    }\\n}\\n```\\n\\n**另外**，实际开发中，如果想要实现某一段功能代码，可以根据用户系统的API版本进行调整，\\n\\n可以使用  **@kit.BasicServicesKit**中的**sdkApiVersion**来实现，如\\n\\n```typescript\\nif(deviceInfo.sdkApiVersion===20){\\n      console.log(\\\"API20\\\")\\n    }\\n```\\n\\n或者在ArkUI中使用 \\n\\n```typescript\\nif (this.sdkApiVersion >= 20) {\\nText('应用20')\\n} else {\\nText('应用不是20')\\n}\\n```\\n\\n\\n\\n### 界面级一多\\n\\n界面一多指的是如何使用一套代码，实现适配多种宽度不同的设备，HarmonyOS中提供的解决方案主要有\\n\\n1. 自适应布局\\n2. 响应式布局\\n\\n所谓的自适应布局可以理解为就是页面布局元素可以跟随屏幕的大小变化而等比例变化。\\n\\n响应式布局则是可以根据不同的条件，实现屏幕布局更大的变化，如\\n\\n1. 大屏幕，一行显示4个卡片\\n2. 小屏幕，一行显示1个卡片。\\n\\n\\n\\n自适应布局比较好实现，像flex容器、grid、线性布局等可以跟随屏幕宽度变化而变化的容器，都可以轻易实现自适应布局，结合尺寸的百分百单位，或者layoutWeight属性，页面元素也可以直接实现自适应布局。\\n\\n针对常见的开发场景，方舟开发框架提炼了七种自适应布局能力，这些布局可以独立使用，也可多种布局叠加使用。\\n\\n| 自适应布局类别 | 自适应布局能力                                               | 使用场景                                                     | 实现方式                                                     |\\n| :------------- | :----------------------------------------------------------- | :----------------------------------------------------------- | :----------------------------------------------------------- |\\n| 自适应拉伸     | [拉伸能力](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-multi-device-adaptive-layout#拉伸能力) | 容器组件尺寸发生变化时，增加或减小的空间**全部分配**给容器组件内**指定区域**。 | [Flex布局](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-universal-attributes-flex-layout)的flexGrow和flexShrink属性 |\\n|                | [均分能力](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-multi-device-adaptive-layout#均分能力) | 容器组件尺寸发生变化时，增加或减小的空间**均匀分配**给容器组件内**所有空白区域**。 | [Row组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-row)、[Column组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-column)或[Flex组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-flex)的justifyContent属性设置为FlexAlign.SpaceEvenly |\\n| 自适应缩放     | [占比能力](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-multi-device-adaptive-layout#占比能力) | 子组件的宽或高**按照预设的比例**，随容器组件发生变化。       | 基于通用属性的两种实现方式：- 将子组件的宽高设置为父组件宽高的百分比- layoutWeight属性 |\\n|                | [缩放能力](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-multi-device-adaptive-layout#缩放能力) | 子组件的宽高**按照预设的比例**，随容器组件发生变化，且变化过程中子组件的**宽高比不变**。 | [布局约束](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-universal-attributes-layout-constraints)的aspectRatio属性 |\\n| 自适应延伸     | [延伸能力](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-multi-device-adaptive-layout#延伸能力) | 容器组件内的子组件，按照其**在列表中的先后顺序**，随容器组件尺寸变化显示或隐藏。 | 基于容器组件的两种实现方式：- 通过[List组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list)实现- 通过[Scroll组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-scroll)配合[Row组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-row)或[Column组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-column)实现 |\\n|                | [隐藏能力](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-multi-device-adaptive-layout#隐藏能力) | 容器组件内的子组件，按照其**预设的显示优先级**，随容器组件尺寸变化显示或隐藏。**相同显示优先级的子组件同时显示或隐藏**。 | [布局约束](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-universal-attributes-layout-constraints)的displayPriority属性 |\\n| 自适应折行     | [折行能力](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-multi-device-adaptive-layout#折行能力) | 容器组件尺寸发生变化时，如果布局方向尺寸不足以显示完整内容，**自动换行**。 | [Flex组件](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-flex)的wrap属性设置为FlexWrap.Wr |\\n\\n更加常用的其实是**响应式布局**\\n\\n响应式布局有四种实现方式，其中它们又可以互相搭配和关联，它们分别是断点、媒体查询以及栅格布局以及响应式工具。\\n\\n**断点 (Breakpoints)**将设备的窗口宽度（或高宽比）划分为几个关键的范围（区间）\\n\\n- xs (超小): 0 ~ 320vp （智能穿戴）\\n- sm (小): 320vp ~ 600vp （手机竖屏）\\n- md (中): 600vp ~ 840vp （平板竖屏/折叠屏）\\n- lg (大): 840vp ~ 1440vp （平板横屏/PC）\\n- xl (超大): 1440vp及以上 （大屏设备）\\n\\n![image-20251030221518090](assets/image-20251030221518090.png)\\n\\n实际开发中，可以监听[屏幕尺寸](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/arkts-apis-window-window#onwindowsizechange7)的变化，然后把断点存储在全局中，方便使用。**宠知汇** 就是采用这种方式。\\n\\n### 宠知汇的屏幕适配流程\\n\\n#### 1.  V2 状态管理设计\\n\\n文件：`commons/base/src/main/ets/utils/BreakpointSystem.ets`\\n\\n**全局状态类定义：**\\n\\n```typescript\\n// 全局断点状态管理（V2）\\n@ObservedV2\\nclass BreakpointState {\\n  @Trace currentBreakpoint: string = 'sm';\\n}\\n\\n// 创建全局单例\\nconst breakpointState = new BreakpointState();\\n\\n// 导出供其他模块使用\\nexport { breakpointState };\\n```\\n\\n**关键设计要点：**\\n- 使用 `@ObservedV2` 装饰器标记可观察类\\n- 使用 `@Trace` 装饰器追踪 `currentBreakpoint` 属性变化\\n- 全局单例模式确保状态一致性\\n- 导出 `breakpointState` 供其他模块直接订阅\\n\\n**断点配置：**\\n\\n```typescript\\ninterface Breakpoint {\\n  name: string;\\n  size: number;\\n}\\n\\nprivate breakpoints: Breakpoint[] = [\\n  { name: 'xs', size: 0 },      // 超小屏（0-320vp）\\n  { name: 'sm', size: 320 },    // 小屏（320-600vp）\\n  { name: 'md', size: 600 },    // 中屏/平板（600-840vp）\\n  { name: 'lg', size: 840 }     // 大屏/折叠屏（840vp+）\\n];\\n```\\n\\n断点划分遵循 HarmonyOS 官方建议，覆盖主流设备尺寸：\\n- **xs/sm**：手机竖屏模式\\n- **md**：平板或手机横屏\\n- **lg**：大屏平板、折叠屏展开状态\\n\\n#### 2.  窗口尺寸监听机制\\n\\n在 API 18 中，推荐使用 `window.on('windowSizeChange')` 替代已废弃的 `mediaquery.matchMediaSync`：\\n\\n```typescript\\n// 注册断点监听\\npublic register(windowClass: window.Window): void {\\n  try {\\n    this.windowClass = windowClass;\\n    this.uiContext = windowClass.getUIContext();\\n    \\n    // 获取初始窗口尺寸并计算断点\\n    const windowProperties = windowClass.getWindowProperties();\\n    const initialWidth = this.uiContext.px2vp(windowProperties.windowRect.width);\\n    const initialBreakpoint = this.calculateBreakpoint(initialWidth);\\n    this.updateCurrentBreakpoint(initialBreakpoint);\\n\\n    // 监听窗口尺寸变化\\n    this.windowSizeChangeCallback = (size: window.Size) => {\\n      if (this.uiContext) {\\n        const newWidth = this.uiContext.px2vp(size.width);\\n        const newBreakpoint = this.calculateBreakpoint(newWidth);\\n        this.updateCurrentBreakpoint(newBreakpoint);\\n      }\\n    };\\n\\n    windowClass.on('windowSizeChange', this.windowSizeChangeCallback);\\n    console.info('[BreakpointSystem] Window size change listener registered');\\n  } catch (err) {\\n    console.error(`[BreakpointSystem] Failed to register: ${JSON.stringify(err)}`);\\n  }\\n}\\n```\\n\\n**关键技术点：**\\n1. 使用 `window.getWindowProperties()` 获取窗口实际尺寸\\n2. 通过 `UIContext.px2vp()` 进行像素到虚拟像素的转换\\n3. 监听窗口尺寸变化事件，支持分屏、折叠屏等场景\\n\\n#### 3. V2 状态更新机制\\n\\n**状态初始化：**\\n\\n```typescript\\n// 注册断点监听时初始化状态\\nconst windowProperties = windowClass.getWindowProperties();\\nconst initialWidth = this.uiContext.px2vp(windowProperties.windowRect.width);\\nconst initialBreakpoint = this.calculateBreakpoint(initialWidth);\\n\\n// 直接更新 V2 状态\\nthis.state.currentBreakpoint = initialBreakpoint;\\n// 同步到 AppStorage（兼容旧版订阅）\\nAppStorage.setOrCreate<string>('currentBreakpoint', initialBreakpoint);\\n```\\n\\n**窗口尺寸变化响应：**\\n\\n```typescript\\nthis.windowSizeChangeCallback = (size: window.Size) => {\\n  if (this.uiContext) {\\n    const newWidth = this.uiContext.px2vp(size.width);\\n    const newBreakpoint = this.calculateBreakpoint(newWidth);\\n    \\n    // 仅在断点实际变化时更新\\n    if (this.state.currentBreakpoint !== newBreakpoint) {\\n      // V2 状态自动触发响应式更新\\n      this.state.currentBreakpoint = newBreakpoint;\\n      // 同步到 AppStorage\\n      AppStorage.setOrCreate<string>('currentBreakpoint', newBreakpoint);\\n      console.info(`[BreakpointSystem] Breakpoint changed to: ${newBreakpoint}`);\\n    }\\n  }\\n};\\n```\\n\\n**V2 状态管理优势：**\\n1. **精准追踪**：`@Trace` 装饰器实现属性级别的变化追踪\\n2. **自动更新**：状态变化自动触发订阅组件的 UI 刷新\\n3. **性能优化**：仅在断点实际变化时触发更新，避免不必要的重渲染\\n4. **双向兼容**：V2 状态与 AppStorage 双向同步，支持新旧两种订阅方式\\n\\n#### 4. 应用生命周期集成\\n\\n文件：`products/phone/src/main/ets/entryability/EntryAbility.ets`\\n\\n```typescript\\nexport default class EntryAbility extends UIAbility {\\n  private breakpointSystem: BreakpointSystem = new BreakpointSystem();\\n\\n  onWindowStageCreate(windowStage: window.WindowStage): void {\\n    windowStage.loadContent('pages/Index', (err) => {\\n      if (err.code) {\\n        hilog.error(DOMAIN, 'testTag', 'Failed to load the content. Cause: %{public}s', \\n                   JSON.stringify(err));\\n        return;\\n      }\\n      // 注册断点监听，传入 Window 实例\\n      this.breakpointSystem.register(windowStage.getMainWindowSync());\\n    });\\n  }\\n\\n  onWindowStageDestroy(): void {\\n    // 注销断点监听\\n    this.breakpointSystem.unregister();\\n    hilog.info(DOMAIN, 'testTag', 'Breakpoint system unregistered');\\n  }\\n}\\n```\\n\\n**生命周期管理：**\\n- 在 `onWindowStageCreate` 中注册断点监听\\n- 在 `onWindowStageDestroy` 中注销监听，避免内存泄漏\\n\\n#### 5. 断点值映射工具\\n\\n```typescript\\n// 断点类型映射\\nexport interface BreakpointTypeOption<T> {\\n  xs?: T;\\n  sm?: T;\\n  md?: T;\\n  lg?: T;\\n}\\n\\n// 断点值映射工具类\\nexport class BreakpointType<T> {\\n  private options: BreakpointTypeOption<T>;\\n\\n  constructor(options: BreakpointTypeOption<T>) {\\n    this.options = options;\\n  }\\n\\n  getValue(breakpoint: string): T | undefined {\\n    if (breakpoint === 'xs') return this.options.xs;\\n    if (breakpoint === 'sm') return this.options.sm;\\n    if (breakpoint === 'md') return this.options.md;\\n    if (breakpoint === 'lg') return this.options.lg;\\n    return undefined;\\n  }\\n}\\n```\\n\\n`BreakpointType` 提供了类型安全的断点值映射机制，支持任意类型的响应式配置。\\n\\n#### 6. UI V2 组件状态管理\\n\\n文件：`products/phone/src/main/ets/pages/HomePage.ets`\\n\\n**组件状态定义：**\\n\\n```typescript\\n// 页面状态类（V2）\\n@ObservedV2\\nclass HomePageState {\\n  @Trace currentPetIndex: number = 0;\\n  @Trace showPetTip: boolean = false;\\n  @Trace petTipText: string = '';\\n}\\n\\n// 组件定义\\n@Component\\nexport struct HomePage {\\n  state: HomePageState = new HomePageState();\\n  @StorageProp('currentBreakpoint') currentBreakpoint: string = 'sm';\\n\\n  build() {\\n    Column() {\\n      Scroll() {\\n        Column({\\n          space: new BreakpointType({\\n            xs: 16,\\n            sm: 20,\\n            md: 24,\\n            lg: 28\\n          }).getValue(this.currentBreakpoint) || 20\\n        }) {\\n          // 页面内容\\n        }\\n        .padding({\\n          left: new BreakpointType({\\n            xs: 16,\\n            sm: 16,\\n            md: 24,\\n            lg: 32\\n          }).getValue(this.currentBreakpoint) || 16,\\n          right: new BreakpointType({\\n            xs: 16,\\n            sm: 16,\\n            md: 24,\\n            lg: 32\\n          }).getValue(this.currentBreakpoint) || 16\\n        })\\n      }\\n    }\\n  }\\n}\\n```\\n\\n通过 `@StorageProp` 订阅全局断点状态，根据不同断点动态调整：\\n- **间距**：xs(16) → sm(20) → md(24) → lg(28)\\n- **内边距**：xs/sm(16) → md(24) → lg(32)\\n\\n**页面间距与尺寸适配：**\\n\\n```typescript\\nbuild() {\\n  Column() {\\n    Scroll() {\\n      Column({\\n        space: new BreakpointType({\\n          xs: 16,\\n          sm: 20,\\n          md: 24,\\n          lg: 28\\n        }).getValue(this.currentBreakpoint) || 20\\n      }) {\\n        // 页面内容\\n      }\\n      .padding({\\n        left: new BreakpointType({\\n          xs: 16,\\n          sm: 16,\\n          md: 24,\\n          lg: 32\\n        }).getValue(this.currentBreakpoint) || 16,\\n        right: new BreakpointType({\\n          xs: 16,\\n          sm: 16,\\n          md: 24,\\n          lg: 32\\n        }).getValue(this.currentBreakpoint) || 16\\n      })\\n    }\\n  }\\n}\\n```\\n\\n通过 `@StorageProp` 订阅全局断点状态，根据不同断点动态调整：\\n- **间距**：xs(16) → sm(20) → md(24) → lg(28)\\n- **内边距**：xs/sm(16) → md(24) → lg(32)\\n\\n#### 7. 栅格布局响应式配置\\n\\n```typescript\\nGrid() {\\n  GridItem() { this.buildFeatureCard('领养', '🐾', ...) }\\n  GridItem() { this.buildFeatureCard('寄养', '🏡', ...) }\\n  GridItem() { this.buildFeatureCard('医疗', '🏥', ...) }\\n  GridItem() { this.buildFeatureCard('美容', '✨', ...) }\\n}\\n.columnsTemplate(\\n  new BreakpointType({\\n    xs: '1fr 1fr',           // 手机：2列\\n    sm: '1fr 1fr',           // 小屏：2列\\n    md: '1fr 1fr 1fr 1fr',   // 平板：4列\\n    lg: '1fr 1fr 1fr 1fr'    // 大屏：4列\\n  }).getValue(this.currentBreakpoint) || '1fr 1fr'\\n)\\n.rowsTemplate(\\n  new BreakpointType({\\n    xs: '1fr 1fr',           // 手机：2行\\n    sm: '1fr 1fr',\\n    md: '1fr',               // 平板：1行\\n    lg: '1fr'\\n  }).getValue(this.currentBreakpoint) || '1fr 1fr'\\n)\\n.columnsGap(\\n  new BreakpointType({\\n    xs: 12,\\n    sm: 12,\\n    md: 16,\\n    lg: 20\\n  }).getValue(this.currentBreakpoint) || 12\\n)\\n```\\n\\n**响应式布局策略：**\\n- 手机端（xs/sm）：2列2行，紧凑布局\\n- 平板端（md/lg）：4列1行，横向展开\\n\\n#### 8. 字体与图标尺寸适配\\n\\n```typescript\\nText('爱宠之家')\\n  .fontSize(new BreakpointType({\\n    xs: 20,\\n    sm: 20,\\n    md: 24,\\n    lg: 28\\n  }).getValue(this.currentBreakpoint) || 20)\\n  .fontWeight(FontWeight.Bold)\\n\\nImage($r('app.media.pet_heart'))\\n  .width(new BreakpointType({\\n    xs: 32,\\n    sm: 32,\\n    md: 40,\\n    lg: 48\\n  }).getValue(this.currentBreakpoint) || 32)\\n  .height(new BreakpointType({\\n    xs: 32,\\n    sm: 32,\\n    md: 40,\\n    lg: 48\\n  }).getValue(this.currentBreakpoint) || 32)\\n```\\n\\n#### 9. 条件布局切换\\n\\n```typescript\\n// 故事卡片 - 在平板上使用横向布局\\nif (this.currentBreakpoint === 'md' || this.currentBreakpoint === 'lg') {\\n  Row({ space: new BreakpointType({ md: 16, lg: 20 }).getValue(this.currentBreakpoint) || 16 }) {\\n    this.buildStoryCard('小橘的新家', '...', '2小时前')\\n    this.buildStoryCard('旺财的康复日记', '...', '1天前')\\n  }\\n} else {\\n  Column({ space: 12 }) {\\n    this.buildStoryCard('小橘的新家', '...', '2小时前')\\n    this.buildStoryCard('旺财的康复日记', '...', '1天前')\\n  }\\n}\\n```\\n\\n根据断点切换布局方向，提升大屏设备的空间利用率。\\n\\n#### 10. 内容宽度约束\\n\\n```typescript\\n.width('100%')\\n.constraintSize({\\n  maxWidth: this.currentBreakpoint === 'xs' || this.currentBreakpoint === 'sm' ? '100%' :\\n    this.currentBreakpoint === 'md' ? 800 : 1200\\n})\\n```\\n\\n在大屏设备上限制内容最大宽度，避免内容过度拉伸导致阅读体验下降。\\n\\n\\n\\n#### 11. 全局状态订阅模式\\n\\n直接订阅 V2 状态\\n\\n```typescript\\nimport { breakpointState } from 'base';\\n\\n@ComponentV2\\nexport struct SomePage {\\n  // 直接引用全局状态\\n  private breakpoint = breakpointState;\\n  \\n  build() {\\n    Text(this.breakpoint.currentBreakpoint)\\n  }\\n}\\n```\\n\\n\\n## 第二章：HarmonyOS 智能体，实现智能化宠物服务\\n\\n\\n\\n《宠知汇》背后依靠海量的宠物饲养百科技术，包含有宠物种类、喂养食物、陪伴技巧、注意事项等等专业知识，利用HarmonyOS上的智能体知识打造出配套可用的智能体，给广大HarmonyOS用户提供贴心帮助。\\n\\n利用 **Agent  Framework Kit** 功能实现在应用内拉起相关智能体，第一时间提供给用户使用的宠物饲养知识。\\n\\n开发者接入智能体只需要两个步骤\\n\\n1. 小艺智能体平台中创建智能体\\n2. 你的应用中引入智能体\\n\\n\\n\\n![image-20251031101602362](assets/image-20251031101602362.png)\\n\\n### 创建智能体\\n\\n#### 1. 登录小艺智能体平台\\n\\n> https://developer.huawei.com/consumer/cn/hag/abilityportal/#/\\n\\n登录华为账号即可\\n\\n![](assets/image-20251031095114165.png)\\n\\n\\n\\n#### 2. 快速创建智能体\\n\\n在小艺智能体平台，智能体是一个最终的产品，智能体可以通过知识库、工作流、和资源来增强自身的功能。\\n\\n![image-20251031095213872](assets/image-20251031095213872.png)\\n\\n#### 3. 配置智能体\\n\\n![](assets/image-20251031095408911.png)\\n\\n刚入门的小伙伴可以选择 **单Agent （LLM模式）**\\n\\n![image-20251031095711444](assets/image-20251031095711444.png)\\n\\n智能体提供了很多配置项\\n\\n这些配置从交互开场、多模态体验、功能扩展、自动化流程、数据管理及用户引导等方面，全方位定制智能体的交互方式、功能范围与运行逻辑，助力其实现个性化、高效且专业的服务。\\n\\n| 配置项       | 作用                                                         |\\n| ------------ | ------------------------------------------------------------ |\\n| 开场对话     | 设置智能体与用户初次交互的开场白，建立初始沟通场景。         |\\n| 输入文件设置 | 配置可上传的文件类型、大小等，支持智能体处理用户上传的文件。 |\\n| 用户问题建议 | 开启后为用户提供问题示例或引导，帮助用户发起提问。           |\\n| 快捷指令     | 可设置最多 10 条快捷指令，用户通过指令快速触发特定功能或流程，提升交互效率。 |\\n| 背景图片     | 设置智能体界面的背景图片，美化界面、营造特定氛围。           |\\n| 角色声音     | 开启后智能体以特定声音交互，增强语音交互的体验感和角色辨识度。 |\\n| 插件         | 可配置最多 20 个插件，扩展智能体功能，如接入工具、调用外部服务等。 |\\n| 工作流       | 可配置最多 20 个工作流，定义复杂任务的自动化处理流程。       |\\n| 触发器       | 可设置最多 10 个触发器，满足特定条件时自动触发相应动作或对话。 |\\n| 关联应用     | 可关联最多 10 个应用，实现与应用的数据交互或功能联动。       |\\n| 知识库       | 可配置最多 10 个知识库，存储特定领域知识，支持智能体专业回答问题。 |\\n| 变量         | 定义和管理交互中的动态数据，支持个性化、动态交互逻辑。       |\\n| 长期记忆     | 开启后智能体记住长期交互信息，保持对话的连续性。             |\\n\\n#### 4. 发布上架智能体\\n\\n如果都编辑完毕了，可以申请上架了\\n\\n![image-20251031100022405](assets/image-20251031100022405.png)\\n\\n\\n\\n如果上架成功，想要让这个智能体给你的鸿蒙应用服务，需要在配置页面中，添加你的**应用**\\n\\n![image-20251031100222985](assets/image-20251031100222985.png)\\n\\n\\n\\n最后需要记住这个智能体的agentId，编码中需要用到的。\\n\\n![image-20251031100340244](assets/image-20251031100340244.png)\\n\\n\\n\\n### 代码中集成\\n\\n\\n#### 1. 导入依赖\\n\\n```ts\\nimport { BusinessError } from '@kit.BasicServicesKit';\\nimport { hilog } from '@kit.PerformanceAnalysisKit';\\nimport { FunctionComponent, FunctionController } from '@kit.AgentFrameworkKit';\\n```\\n\\n#### 2. 声明控制器与智能体标识\\n\\n```ts\\n// 智能体控制器（用于监听对话框打开/关闭等事件）\\nprivate agentController: FunctionController = new FunctionController();\\n\\n// 智能体实例标识（需替换为实际可用的 agentId）\\nprivate agentId: string = 'agenta6912c10c332438aa25f7e25da306eba';\\n```\\n\\n#### 3. 生命周期中注册/释放事件监听\\n\\n```ts\\naboutToAppear() {\\n  // 初始化事件监听器\\n  this.initAgentListeners();\\n}\\n\\naboutToDisappear() {\\n  // 释放事件监听器，避免内存泄漏\\n  this.agentController?.off('agentDialogOpened');\\n  this.agentController?.off('agentDialogClosed');\\n}\\n\\n// 统一初始化监听\\ninitAgentListeners() {\\n  this.agentController?.on('agentDialogOpened', this.onAgentOpenedCallback);\\n  this.agentController?.on('agentDialogClosed', this.onAgentClosedCallback);\\n}\\n\\n// 回调方法\\nonAgentOpenedCallback = () => {\\n  hilog.info(0x0001, 'HomePage', '智能体弹窗已打开');\\n}\\nonAgentClosedCallback = () => {\\n  hilog.info(0x0001, 'HomePage', '智能体弹窗已关闭');\\n}\\n```\\n\\n#### 4. 在页面中渲染 FunctionComponent\\n\\n```ts\\n@Builder\\nbuildAIAssistantButton() {\\n  // 放置位置可根据页面布局自行调整\\n  Column() {\\n    FunctionComponent({\\n      agentId: this.agentId,\\n      onError: (err: BusinessError) => {\\n        hilog.error(0x0001, 'HomePage', `智能体错误: ${JSON.stringify(err)}, message: ${err.message}`);\\n      },\\n      options: {\\n        title: '你的宠物百科',\\n        isShowShadow: true\\n      },\\n      controller: this.agentController\\n    })\\n  }\\n  .margin({\\n    right: 16, // 可结合断点系统做响应式\\n    bottom: 80\\n  })\\n}\\n```\\n\\n说明：\\n- `agentId` 用于绑定具体的智能体能力。\\n- `controller` 负责事件监听与交互控制。\\n- `onError` 对接错误处理与日志记录。\\n- `options` 可配置标题与视觉效果等。\\n\\n#### 5. 完整最小示例（页面片段）\\n\\n```ts\\n@Component\\nexport struct HomePage {\\n  private agentController: FunctionController = new FunctionController();\\n  private agentId: string = 'agenta6912c10cxxxxxxxxxxxxxx';\\n\\n  aboutToAppear() {\\n    this.initAgentListeners();\\n  }\\n\\n  aboutToDisappear() {\\n    this.agentController?.off('agentDialogOpened');\\n    this.agentController?.off('agentDialogClosed');\\n  }\\n\\n  initAgentListeners() {\\n    this.agentController?.on('agentDialogOpened', () => {\\n      hilog.info(0x0001, 'HomePage', '智能体弹窗已打开');\\n    });\\n    this.agentController?.on('agentDialogClosed', () => {\\n      hilog.info(0x0001, 'HomePage', '智能体弹窗已关闭');\\n    });\\n  }\\n\\n  build() {\\n    // ...页面主体内容\\n\\n    // 在右下角叠加智能体入口\\n    Stack({ alignContent: Alignment.BottomEnd }) {\\n      // ...其他内容\\n      this.buildAIAssistantButton()\\n    }\\n    .width('100%')\\n    .height('100%')\\n  }\\n\\n  @Builder\\n  buildAIAssistantButton() {\\n    Column() {\\n      FunctionComponent({\\n        agentId: this.agentId,\\n        onError: (err: BusinessError) => {\\n          hilog.error(0x0001, 'HomePage', `智能体错误: ${JSON.stringify(err)}, message: ${err.message}`);\\n        },\\n        options: {\\n          title: '你的宠物百科',\\n          isShowShadow: true\\n        },\\n        controller: this.agentController\\n      })\\n    }\\n    .margin({ right: 16, bottom: 80 })\\n  }\\n}\\n```\\n\\n#### 6. 常见问题与建议\\n\\n- 智能体 API 能力提示：部分设备或 API 版本可能提示\\\"系统能力不支持\\\"，请确保目标设备及系统版本支持 AgentFramework 能力。\\n- `agentId` 必须为有效的智能体标识；如无效会触发 `onError`。\\n- 事件监听务必在 `aboutToDisappear` 释放，避免资源泄漏。\\n- 放置位置与样式可结合现有断点系统进行响应式适配。\\n\\n\\n\\n \\n\\n## 第三章：其他优秀Harmony6 特性\\n\\n### 1. enableDataDetector - 智能实体识别\\n全新的智能实体识别能力，能够自动识别文本中的电话号码、邮箱、网址、地址等实体信息。\\n\\n**实际应用**：\\n\\n```typescript\\nText('邮箱：yeah126139163@163.com')\\n  .enableDataDetector(true)  // 启用实体识别\\n  .dataDetectorConfig({\\n    // 支持识别类型：PHONE_NUMBER、URL、EMAIL、ADDRESS、DATE_TIME\\n    types: [],  // 空数组表示识别所有类型\\n    onDetectResultUpdate: (result: string) => {\\n      // 识别结果回调处理\\n    }\\n  })\\n```\\n\\n### 2. showCommentDialog - 应用商店评论对话框\\n\\n![拿已经上架 作品演示](assets/image-20251031085235546.png)\\n\\n鸿蒙6新增的应用商店评论API，可在应用内直接调起评论对话框。\\n\\n```typescript\\nconst uiContext = this.getUIContext().getHostContext() as common.UIAbilityContext;\\ncommentManager.showCommentDialog(uiContext).then(() => {\\n  hilog.info(0, 'TAG', \\\"评论对话框显示成功\\\");\\n}).catch((error: BusinessError<Object>) => {\\n  // 处理用户短期内已评论的情况\\n  this.getUIContext().getPromptAction().showToast({ \\n    message: `您短期内已经评论过了` \\n  });\\n});\\n```\\n\\n### 3. shaderStyle - 着色器样式渲染\\n鸿蒙6引入的GPU加速着色器渲染技术，支持渐变色、阴影等高级视觉效果。\\n\\n```typescript\\nText('应用名称')\\n  .shaderStyle({\\n    colors: [[Color.Red, 0], [Color.Orange, 1]],  // 渐变色配置\\n    direction: GradientDirection.Right            // 渐变方向\\n  })\\n```\\n\\n### 4. animationCurve - 动画曲线优化\\n鸿蒙6优化的动画曲线系统，提供更自然流畅的动画效果。\\n\\n```typescript\\nTabs({ index: $$this.currentTabIndex })\\n  .onChange((index: number) => {\\n    this.currentTabIndex = index;\\n  })\\n  .animationCurve(Curve.EaseInOut)  // 缓入缓出动画曲线\\n```\\n\\n###  5. 文本翻牌动效 contentTransition\\n\\n![image-20251031090516298](assets/image-20251031090516298.png)\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nstruct ScheduleDetailPage {\\n  @Local number: number = 5;\\n  @Local numberTransition: NumericTextTransition = new NumericTextTransition({ flipDirection: FlipDirection.DOWN, enableBlur: false });\\n\\n  build() {\\n    Column() {\\n      Text(this.number + \\\"\\\")\\n        .borderWidth(1)\\n        .fontSize(40)\\n        .contentTransition(this.numberTransition)\\n      Button(\\\"chang number\\\")\\n        .onClick(() => {\\n          this.number++;\\n        })\\n        .margin(10)\\n    }\\n    .height('100%')\\n    .width('100%')\\n  }\\n}\\n```\\n\\n\\n\\n## 结言\\n\\n \\n\\n以极小的代码代价让《宠知汇》接入了鸿蒙新的特性，通过引入了一多、智能体能力，HarmonyOS应用上实现了其他系统没有的创新体验，带给用户丝滑、流畅的体验。\\n\\n \"}"),u={name:"鸿蒙开发技巧/《宠知汇》应用案例热点技术解析/《宠知汇》应用案例热点技术解析.md"};function m(C,s,B,A,D,v){return n(),a("div",null,[...s[0]||(s[0]=[l("",177)])])}const x=i(u,[["render",m]]);export{w as __pageData,x as default};
